// Maps API error codes to translated text. Exhaustive on purpose: a new server
// error code (Rust `ErrorCode`, regenerated by `make types`) fails the type check here.
import type { MessageKey } from '@cloudit/ui/i18n';
import { ApiError, type ClientErrorCode } from './api';

const MESSAGE_KEYS: Record<ClientErrorCode, MessageKey> = {
  bad_request: 'error.bad_request',
  not_found: 'error.not_found',
  unavailable: 'error.unavailable',
  internal: 'error.internal',
  unauthorized: 'error.unauthorized',
  forbidden: 'error.forbidden',
  invalid_credentials: 'error.invalid_credentials',
  account_disabled: 'error.account_disabled',
  registration_closed: 'error.registration_closed',
  invite_invalid: 'error.invite_invalid',
  token_invalid: 'error.token_invalid',
  email_taken: 'error.email_taken',
  validation_failed: 'error.validation_failed',
  rate_limited: 'error.rate_limited',
  csrf_failed: 'error.csrf_failed',
  setup_required: 'error.setup_required',
  setup_already_done: 'error.setup_already_done',
  setup_token_invalid: 'error.setup_token_invalid',
  last_admin: 'error.last_admin',
  provider_not_found: 'error.provider_not_found',
  provider_id_taken: 'error.provider_id_taken',
  provider_discovery_failed: 'error.provider_discovery_failed',
  provider_error: 'error.provider_error',
  public_url_required: 'error.public_url_required',
  provider_disabled: 'error.provider_disabled',
  oauth_state_invalid: 'error.oauth_state_invalid',
  oauth_cancelled: 'error.oauth_cancelled',
  group_not_allowed: 'error.group_not_allowed',
  identity_in_use: 'error.identity_in_use',
  identity_not_linked: 'error.identity_not_linked',
  onboarding_expired: 'error.onboarding_expired',
  last_login_method: 'error.last_login_method',
  account_pending: 'error.account_pending',
  account_rejected: 'error.account_rejected',
  network: 'error.network',
  unknown: 'error.unknown'
};

/** The i18n key describing any thrown value. */
export function errorMessageKey(err: unknown): MessageKey {
  return err instanceof ApiError ? MESSAGE_KEYS[err.code] : 'error.unknown';
}
